p12e4.sql:
CREATE FUNCTION plan_valor(p_nom_plan CHAR(20), p_fecha DATE) RETURNS DECIMAL(9,3)
DETERMINISTIC READS SQL DATA
BEGIN
  DECLARE v_valor DECIMAL(9,3);
  SELECT valor_plan INTO v_valor
  FROM valores_plan
  WHERE nom_plan = p_nom_plan AND fecha_desde_plan = (
     SELECT MAX(fecha_desde_plan) FROM valores_plan WHERE nom_plan = p_nom_plan AND fecha_desde_plan <= p_fecha
  );
  RETURN v_valor;
END

