CREATE FUNCTION alumnos_deudas_a_fecha(p_dni INT, p_fecha DATE) RETURNS INT
DETERMINISTIC READS SQL DATA
BEGIN
  DECLARE v_cant INT;
  SELECT COUNT(*) INTO v_cant
  FROM cuotas
  WHERE dni = p_dni AND fecha_emision <= p_fecha AND (fecha_pago IS NULL OR fecha_pago > p_fecha);
  RETURN v_cant;
END

p12e10.sql:
DROP PROCEDURE IF EXISTS alumno_inscripcion;
CREATE PROCEDURE alumno_inscripcion(
  IN p_dni INT, IN p_nombre VARCHAR(20), IN p_apellido VARCHAR(20), IN p_tel VARCHAR(20),
  IN p_email VARCHAR(50), IN p_direccion VARCHAR(50),
  IN p_nom_plan CHAR(20), IN p_nro_curso INT)
BEGIN
  DECLARE v_cupo INT;
  DECLARE v_cant INT;

  START TRANSACTION;

  IF NOT EXISTS (SELECT 1 FROM inscripciones WHERE nom_plan = p_nom_plan AND nro_curso = p_nro_curso AND dni = p_dni) THEN
    INSERT INTO alumnos (dni, nombre, apellido, tel, email, direccion)
    VALUES (p_dni, p_nombre, p_apellido, p_tel, p_email, p_direccion)
    ON DUPLICATE KEY UPDATE nombre = nombre;

    INSERT INTO inscripciones (nom_plan, nro_curso, dni, fecha_inscripcion)
    VALUES (p_nom_plan, p_nro_curso, p_dni, CURDATE());

    INSERT INTO cuotas (nom_plan, nro_curso, dni, anio, mes, fecha_emision, fecha_pago, importe_pagado)
    VALUES (p_nom_plan, p_nro_curso, p_dni,
            YEAR(CURDATE() + INTERVAL 1 MONTH), MONTH(CURDATE() + INTERVAL 1 MONTH),
            CURDATE(), NULL, NULL);

    SELECT cupo INTO v_cupo FROM cursos WHERE nom_plan = p_nom_plan AND nro_curso = p_nro_curso;
    SELECT COUNT(*) INTO v_cant FROM inscripciones WHERE nom_plan = p_nom_plan AND nro_curso = p_nro_curso;

    IF v_cant > v_cupo THEN
      ROLLBACK;
      SELECT 'RECHAZADO: se supero el cupo' AS resultado;
    ELSE
      COMMIT;
      SELECT 'OK: inscripcion confirmada' AS resultado;
    END IF;
  ELSE
    ROLLBACK;
    SELECT 'RECHAZADO: ya estaba inscripto' AS resultado;
  END IF;
END

p12e11.sql:
CREATE PROCEDURE stock_movimiento(IN p_cod_material CHAR(6), IN p_cantidad INT, OUT p_restante INT)
BEGIN
  DECLARE v_es_util INT;

  START TRANSACTION;

  SELECT COUNT(*) INTO v_es_util FROM materiales WHERE cod_material = p_cod_material AND cod_material LIKE 'UT-%';

  IF v_es_util = 0 THEN
    ROLLBACK;
    SELECT cant_disponible INTO p_restante FROM materiales WHERE cod_material = p_cod_material;
  ELSE
    UPDATE materiales SET cant_disponible = cant_disponible + p_cantidad WHERE cod_material = p_cod_material;
    SELECT cant_disponible INTO p_restante FROM materiales WHERE cod_material = p_cod_material;

    IF p_restante < 0 THEN
      ROLLBACK;
      SELECT cant_disponible INTO p_restante FROM materiales WHERE cod_material = p_cod_material;
    ELSE
      COMMIT;
    END IF;
  END IF;
END;

CREATE PROCEDURE stock_ingreso(IN p_cod_material CHAR(6), IN p_cantidad INT, OUT p_restante INT)
BEGIN
  CALL stock_movimiento(p_cod_material, p_cantidad, p_restante);
END;

CREATE PROCEDURE stock_egreso(IN p_cod_material CHAR(6), IN p_cantidad INT, OUT p_restante INT)
BEGIN
  CALL stock_movimiento(p_cod_material, -p_cantidad, p_restante);
END;

p12e12.sql:
CREATE PROCEDURE alumno_anula_inscripcion(IN p_dni INT, IN p_nom_plan CHAR(20), IN p_nro_curso INT)
BEGIN
  DECLARE v_pagos INT;
  SELECT COUNT(*) INTO v_pagos FROM cuotas
  WHERE dni = p_dni AND nom_plan = p_nom_plan AND nro_curso = p_nro_curso AND importe_pagado IS NOT NULL;

  IF v_pagos = 0 THEN
    DELETE FROM cuotas WHERE dni = p_dni AND nom_plan = p_nom_plan AND nro_curso = p_nro_curso;
    DELETE FROM evaluaciones WHERE dni = p_dni AND nom_plan = p_nom_plan AND nro_curso = p_nro_curso;
    DELETE FROM inscripciones WHERE dni = p_dni AND nom_plan = p_nom_plan AND nro_curso = p_nro_curso;
    SELECT 'Inscripcion anulada' AS resultado;
  ELSE
